use serde_json::{Value,json};
use std::{fs,collections::BTreeMap};
const R:&str="/home/ubuntu/src/zopro-perf-work/ibs-backing177";
fn median(mut v:Vec<f64>)->f64{assert_eq!(v.len(),3);v.sort_by(f64::total_cmp);v[1]}
fn main(){let v:Value=serde_json::from_slice(&fs::read(format!("{R}/result.json")).unwrap()).unwrap();let rows=v["rows"].as_array().unwrap();let mut out=Vec::new();
    for copy in 0..3{let plain=rows.iter().filter(|r|r["copy"]==copy&&r["panel"]=="plain").collect::<Vec<_>>();
        let mut groups=BTreeMap::new();for panel in["op","fetch"]{let rs=rows.iter().filter(|r|r["copy"]==copy&&r["panel"]==panel).collect::<Vec<_>>();for feed in["G1feed","G2feed"]{let group=format!("user/{feed}");let gs=rs.iter().map(|r|&r["diagnostic"]["analysis"]["groups"][&group]).collect::<Vec<_>>();let get=|f:fn(&Value)->f64|median(gs.iter().map(|g|f(g)).collect());
            let x=if panel=="op"{json!({"samples_median":get(|g|g["samples"].as_f64().unwrap()),"tag_to_complete_mean_median":get(|g|g["tag_to_complete"]["mean"].as_f64().unwrap()),"complete_to_retire_mean_median":get(|g|g["complete_to_retire"]["mean"].as_f64().unwrap()),"L1miss_percent_load_ops":get(|g|100.*g["demand_L1_misses"].as_f64().unwrap()/g["load_ops"].as_f64().unwrap()),"L2miss_percent_load_ops":get(|g|100.*g["demand_L2_misses"].as_f64().unwrap()/g["load_ops"].as_f64().unwrap()),"RAM_total":gs.iter().map(|g|g["demand_RAM"].as_u64().unwrap()).sum::<u64>(),"imprecise_total":gs.iter().map(|g|g["imprecise_excluded"].as_u64().unwrap()).sum::<u64>(),"invalid_saturated_total":gs.iter().map(|g|g["invalid_or_saturated_latency_pairs"].as_u64().unwrap()).sum::<u64>(),"demand_miss_mean_median":get(|g|g["valid_demand_miss_latency"]["mean"].as_f64().unwrap())})}
            else{json!({"samples_median":get(|g|g["samples"].as_f64().unwrap()),"completed_fetch_mean_median":get(|g|g["complete_fetch_latency"]["mean"].as_f64().unwrap()),"complete_percent":get(|g|100.*g["complete"].as_f64().unwrap()/g["samples"].as_f64().unwrap()),"icache_miss_percent":get(|g|100.*g["icache_misses"].as_f64().unwrap()/g["samples"].as_f64().unwrap()),"opcache_miss_percent":get(|g|100.*g["opcache_misses"].as_f64().unwrap()/g["samples"].as_f64().unwrap()),"L2_ITLB_misses_total":gs.iter().map(|g|g["L2_ITLB_misses"].as_u64().unwrap()).sum::<u64>()})};groups.insert(format!("{panel}/{feed}"),x);
        }}
        let cpu=median(plain.iter().map(|r|(r["summary"]["user_cpu_ms"].as_f64().unwrap()+r["summary"]["system_cpu_ms"].as_f64().unwrap())/61.).collect());
        out.push(json!({"copy":copy,"plain_median_ms":median(plain.iter().map(|r|r["mean_ms"].as_f64().unwrap()).collect()),"plain_CPU_ms_per_proof":cpu,"plain_max_RSS_MiB":plain.iter().map(|r|r["summary"]["whole_process_maxrss_kib"].as_f64().unwrap()/1024.).fold(0.,f64::max),"groups":groups}));
    }
    let counts=rows.iter().filter(|r|r["panel"]!="plain").map(|r|r["diagnostic"]["analysis"]["samples"].as_u64().unwrap()).sum::<u64>();
    let s=json!({"copies":out,"total_IBS_samples":counts,"observer_checks":v["observer_checks"],"quality_passed":v["quality_passed"],"observer_checks_passed":v["observer_checks_passed"],"page_frames_compared":v["page_frames_compared"],"page_frames_changed_between_endpoints":v["page_frames_changed_between_endpoints"],"SDK_calls":1728,"timed_samples":1647,"fresh_verified_exports":27,"canonical_count":52972,"aggregation":"median of three process metrics per copy; descriptive only, no intervals or adoption gate"});
    fs::write(format!("{R}/summary.json"),serde_json::to_vec_pretty(&s).unwrap()).unwrap();println!("{}",serde_json::to_string_pretty(&s).unwrap());
}
